require 'json'

input_path = ENV["input_file"]

return false unless File.exist?(input_path)

output_path = File.join(ENV["alfred_workflow_cache"], "data.json")

def valid_json_structure?(input_path, output_path)
  file_content = File.read(input_path)
  json_data = file_content.force_encoding("UTF-8")

  data = JSON.parse(file_content)
  return false unless data['messages'].is_a?(Array)

  data['messages'].each do |msg|
    return false unless msg['role'].is_a?(String) && ['system', 'user', 'assistant'].include?(msg['role'])
    return false if (msg['role'] == "user" && !msg['content'].is_a?(Array))
    return false if (msg['role'] != "user" && !msg['content'].is_a?(String))
  end

  File.write(output_path, JSON.pretty_generate(data))
  print true
end

valid_json_structure?(input_path, output_path)

open_in_app() {
  local localFilePath="$1"
  localFilePath=$(echo $localFilePath | sed 's/:80\//\//g')

  /usr/bin/osascript -l JavaScript <<EOF
var Safari = Application('Safari');
var windows = Safari.windows();
var theURL = "$localFilePath";
var found = false;

for (var i = 0; i < windows.length; i++) {
    var tabs = windows[i].tabs();
    for (var j = 0; j < tabs.length; j++) {
        if (tabs[j].url() == theURL) {
            windows[i].currentTab = tabs[j];
            tabs[j].url = theURL; // Reload the tab
            found = true;
            break;
        }
    }
    if (found) break;
}

if (!found) {
    var newTab = Safari.Tab({ url: theURL });
    Safari.windows[0].tabs.push(newTab);
    Safari.windows[0].currentTab = newTab;
}

Safari.activate();
EOF
}

open_in_app "{query}"

open_in_app() { local appName="$1"
/usr/bin/osascript <<EOF tell application "$appName" activate end tell EOF }
open_in_app "${browser_name}"
